无额外补充'}}</el-descriptions-item><el-descriptions-item label="特殊成本">{{optionalLabel(historyDetail.result,'special_cost')}}</el-descriptions-item><el-descriptions-item label="模摊">{{optionalLabel(historyDetail.result,'tooling_amortization')}}</el-descriptions-item></el-descriptions><p v-for="charge in historyDetail.inputs.treatments" :key="charge.item_key">{{charge.name}}：费率 {{charge.rate}} · {{charge.source}}</p><p v-for="issue in historyDetail.result.issues" :key="issue">{{issue}}</p></section></el-dialog>
