import type { CostingTask, CostingItem, CostingRevision, Candidate, MaterialPrice, ChargeRule, ImportRow, SurfaceTreatment } from '@/types/costing'
import SurfaceTreatmentEditor from '@/components/SurfaceTreatmentEditor.vue'
import PartEditorDialog from '@/components/PartEditorDialog.vue'
const tasks=ref<CostingTask[]>([]), taskId=ref<number>(), items=ref<CostingItem[]>([]), customers=ref<{id:number;name:string}[]>([])
const loading=ref(false),busy=ref(false),error=ref(''),createVisible=ref(false),candidateVisible=ref(false),editorVisible=ref(false),partVisible=ref(false),editorLoading=ref(false),editorError=ref('')
const newTask=reactive({name:'',customer_id:undefined as number|undefined})
