const editing=ref<CostingItem|null>(null),context=ref<any>(null),previewData=ref<any>(null),form=ref<any>({}),reason=ref(''),requestId=ref('')
const catalog=ref<{materials:MaterialPrice[];treatments:ChargeRule[]}>({materials:[],treatments:[]})
const historyVisible=ref(false),history=ref<CostingRevision[]>([]),historyDetail=ref<CostingRevision|null>(null),importVisible=ref(false),importRows=ref<ImportRow[]>([])
const money=(v:unknown)=>v===undefined||v===null?'待补':Number(v).toFixed(6)
const optionalLabel=(result:any,category:string)=>{if(!result)return '待核算';const rows=result.optional_costs.filter((x:any)=>x.category===category&&x.selected);return !rows.length?'未选用':rows.some((x:any)=>x.amount===null)?'待补':money(rows.reduce((sum:number,x:any)=>sum+Number(x.amount),0))}
const num=(v:unknown)=>v===undefined||v===null||v===''?null:Number(v)
const referenceValue=(v:unknown)=>v===undefined||v===null||String(v).trim()===''?'未提供':String(v)
onMounted(async()=>{try{const [t,c,cat]=await Promise.all([costingApi.tasks(),customersApi.list<{items:{id:number;name:string}[]}>({limit:200}),costingApi.catalog()]);tasks.value=t;customers.value=c.items;catalog.value=cat}catch(e){error.value=costingError(e)}})
async function loadTask(){if(!taskId.value)return;loading.value=true;error.value='';try{items.value=(await costingApi.task(taskId.value)).items}catch(e){error.value=costingError(e)}finally{loading.value=false}}
async function createTask(){busy.value=true;try{const t=await costingApi.createTask(newTask);tasks.value=await costingApi.tasks();taskId.value=t.id;await loadTask();createVisible.value=false}catch(e){ElMessage.error(costingError(e))}finally{busy.value=false}}
function openCandidates(){candidateVisible.value=true;candidatePage.value=1;void searchCandidates()}
async function searchCandidates(){if(!selectedTask.value)return;candidateLoading.value=true;try{const r=await costingApi.candidates({customer_id:selectedTask.value.customer_id,keyword:keyword.value,offset:(candidatePage.value-1)*100,limit:100});candidateRows.value=r.items;candidateTotal.value=r.total}catch(e){ElMessage.error(costingError(e))}finally{candidateLoading.value=false}}
async function addCandidate(c:Candidate,source_reference?:Record<string,unknown>){if(!taskId.value)return;busy.value=true;try{await costingApi.addItem(taskId.value,{alias_id:c.alias_id,part_id:c.part_id,tooling_id:c.tooling_id,spec_id:c.spec_id,source_reference:source_reference??null});await loadTask();ElMessage.success('方案已加入，重复加入不会新增同方案')}catch(e){ElMessage.error(costingError(e))}finally{busy.value=false}}
function chooseMaterial(){const m=catalog.value.materials.find(x=>x.id===form.value.material_id);Object.assign(form.value.calculation.material,{density:num(m?.density),material_price:num(m?.material_price),scrap_price:num(m?.scrap_price)})}
function chooseQuote(){const q=context.value.quotes.find((x:any)=>x.item_id===form.value.quote_item_id);if(q)Object.assign(form.value.calculation.material,{density:num(q.density),material_price:num(q.material_price),scrap_price:num(q.scrap_price),utilization_pct:num(q.utilization_pct)})}
watch(()=>form.value.price_source,source=>{if(!form.value.calculation)return;if(source==='catalog')chooseMaterial();else if(source==='quote')chooseQuote()})
function chooseRule(charge:any){const r=catalog.value.treatments.find(x=>x.id===charge.rule_id);if(r){charge.rate=num(r.rate);charge.method=r.calc_mode==='net_weight'?'net_kg':'piece';charge.source=`共用收费规则：${r.name}`}}
function chargesFor(t:SurfaceTreatment,old:any[]=[]){return t.items.map(i=>old.find(c=>c.item_key===i.item_key)||{item_key:i.item_key,name:i.name,rule_id:null,method:'piece',rate:null,quantity:null,source:''})}
async function edit(item:CostingItem){editing.value={...item};editorVisible.value=true;editorLoading.value=true;editorError.value='';previewData.value=null;reason.value='';requestId.value=crypto.randomUUID()
 try{context.value=await costingApi.context(item.id);const c=context.value;const revisions=await costingApi.revisions(item.id);const last=revisions[0]
 form.value={price_source:'catalog',material_id:c.material_id,quote_item_id:null,source_note:'',calculation:{mode:'basic',material:{thickness:num(c.thickness),width:num(c.width),pitch:num(c.pitch),density:null,pieces_per_blank:1,gross_weight_g:num(c.gross_weight_g),net_weight_g:num(c.net_weight_g),quoted_gross_weight_g:null,utilization_pct:null,material_price:null,scrap_price:null},reference_price:null,comparison_basis:'unknown',treatment_status:c.surface_treatment.status,treatments:chargesFor(c.surface_treatment),special_costs:[],tooling_amortization:{selected:false,name:'模摊',amount:null,source:''}}}
 if(last){form.value.calculation=JSON.parse(JSON.stringify(last.inputs));form.value.calculation.reference_price=num(form.value.calculation.reference_price);form.value.calculation.comparison_basis??='unknown';for(const cost of [...form.value.calculation.special_costs,form.value.calculation.tooling_amortization])cost.amount=num(cost.amount);for(const charge of form.value.calculation.treatments){charge.rate=num(charge.rate);charge.quantity=num(charge.quantity)};form.value.price_source=last.context.sources.price_source;form.value.material_id=last.context.sources.material?.id??c.material_id;form.value.quote_item_id=last.context.sources.quote?.item_id??null;form.value.source_note=last.context.sources.note||'';Object.keys(form.value.calculation.material).forEach(k=>{form.value.calculation.material[k]=num(form.value.calculation.material[k])});form.value.calculation.material.net_weight_g=num(c.net_weight_g)??form.value.calculation.material.net_weight_g;form.value.calculation.treatments=chargesFor(c.surface_treatment,form.value.calculation.treatments)}
 if(!form.value.material_id){form.value.material_id=catalog.value.materials.find(m=>m.name===c.material_name||m.code===c.material_name)?.id}
 if(!last&&c.import_source){const source=c.import_source;const values=source.values||{};form.value.source_note=`参考表 ${source.sheet} 第 ${source.row} 行`;if(c.net_weight_g===null)form.value.calculation.material.net_weight_g=num(values.net_weight_g);form.value.calculation.material.gross_weight_g=num(values.gross_weight_g)}
 if(form.value.price_source==='catalog')chooseMaterial();if(form.value.price_source==='quote')chooseQuote()
 }catch(e){editorError.value=costingError(e)}finally{editorLoading.value=false}}
function surfaceSaved(value:SurfaceTreatment){context.value.surface_treatment=value;form.value.calculation.treatment_status=value.status;form.value.calculation.treatments=chargesFor(value,form.value.calculation.treatments);previewData.value=null}
watch(form,()=>{previewData.value=null;requestId.value=crypto.randomUUID()},{deep:true,flush:'sync'})
async function preview(){if(!editing.value)return;busy.value=true;editorError.value='';try{previewData.value=await costingApi.preview(editing.value.id,form.value)}catch(e){editorError.value=costingError(e)}finally{busy.value=false}}
async function save(){if(!editing.value||!previewData.value)return;busy.value=true;editorError.value='';try{const r=await costingApi.save(editing.value.id,{...form.value,expected_source_token:previewData.value.source_token,expected_version:editing.value.version,request_id:requestId.value,reason:reason.value});editing.value.version=r.revision_no;requestId.value=crypto.randomUUID();await loadTask();ElMessage.success(`已保存核算版本 ${r.revision_no}${r.result.total===null?'（资料待完善）':''}`)}catch(e){editorError.value=costingError(e)}finally{busy.value=false}}
async function showHistory(item:CostingItem){try{history.value=await costingApi.revisions(item.id);historyDetail.value=null;historyVisible.value=true}catch(e){ElMessage.error(costingError(e))}}
async function download(){if(!taskId.value)return;try{await costingApi.export(taskId.value)}catch(e){ElMessage.error(costingError(e))}}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!selectedTask.value)return;busy.value=true;try{importRows.value=(await costingApi.importPreview(selectedTask.value.customer_id,file)).rows}catch(e){ElMessage.error(costingError(e))}finally{busy.value=false}}
</script>
