solid #d4e2d8;margin:24px 0}.result-top{display:flex;align-items:center;justify-content:space-between;gap:16px}.result-top strong{display:block;font-size:28px;font-variant-numeric:tabular-nums;margin-top:8px}.result-top small{font-size:13px;font-weight:400}.result-top span,.result-panel p,.result-panel li{font-size:13px}.result-panel li{line-height:1.8;color:#8b5b29}.editor-footer{display:flex;justify-content:flex-end;gap:10px;align-items:center}.editor-footer>span{margin-right:auto;color:#647477;font-size:12px}.history-json{white-space:pre-wrap;max-height:380px;overflow:auto;background:#f4f6f5;padding:18px;font-size:12px}.import-candidate{display:flex;gap:12px;align-items:center;justify-content:space-between}.import-candidate span{font-size:12px}@media(max-width:760px){.costing-page{padding:14px}.page-heading{flex-direction:column}.task-bar .el-select{width:100%}.input-grid{grid-template-columns:1fr}.charge-grid{grid-template-columns:1fr}.optional-row{flex-wrap:wrap}.optional-row .el-input{flex-basis:100%}.result-top{align-items:flex-start;flex-direction:column}.editor-footer{flex-wrap:wrap}}
</style>
